/* From Uiverse.io by TasneemHatem97 - Tags: form, password, login form */
.__UIV_SCOPE__ .container {
  max-width: 300px;
  background-color: #F1F7FE;
  border-radius: 15px;
  overflow: hidden;
}

.__UIV_SCOPE__ form {
  display: flex;
  align-items: center;
  flex-direction: column;
  padding: 32px 24px 24px;
  gap: 16px;
  text-align: center;
}

.__UIV_SCOPE__ form .head {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.__UIV_SCOPE__ form .head span {
  font-size: 1.6rem;
  font-weight: bolder;
  color: black;
}

.__UIV_SCOPE__ form .head p {
  font-size: 1.1rem;
  color: #7C6666;
}

.__UIV_SCOPE__ form .inputs {
  overflow: hidden;
  background-color: #fff;
  width: 100%;
  margin: 1rem 0.5rem;
  border-radius: 8px;
  border-bottom: none;
  outline: 0;
}

.__UIV_SCOPE__ form .inputs input {
  border: none;
  outline: none;
  padding: 8px 15px;
    /* علشان اقدر اخلي البلاس هولدر من اول الفورم بديله نفس الويدس */
  width: 100%;
  height: 40px;
  border-bottom: 1px solid rgba(128, 128, 128, 0.299);
  font-weight: 200;
}

.__UIV_SCOPE__ form button {
  background-color: #4287ef;
  color: white;
  width: 100%;
  height: 40px;
  padding-top: 8px;
  padding-bottom: 8px;
  border: 0;
  overflow: hidden;
  border-radius: 25px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 1s ease-in-out;
}

.__UIV_SCOPE__ form button:hover {
  background-color: #005ce6;
}

.__UIV_SCOPE__ .form-footer {
  background-color: #e0ecfb;
  padding: 16px;
  font-size: 1rem;
  text-align: center;
}

.__UIV_SCOPE__ .form-footer a {
  font-weight: bolder;
  color: #0066ff;
  transition: all 3s ease-in-out;
}

.__UIV_SCOPE__ .form-footer a:hover {
  color: #005ce6;
}
